// Transaction executes fn within a database transaction, rolling back on error.
func (c *TableClient[T]) Transaction(ctx context.Context, fn func(tx *sql.Tx) error) error {
	tx, err := c.DB.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer func() {
		if p := recover(); p != nil {
			_ = tx.Rollback()
			panic(p)
		}
	}()
	if err := fn(tx); err != nil {
		_ = tx.Rollback()
		return err
	}
	return tx.Commit()
}

// parseArgs is the generic where/orderBy/take/skip extractor.
// It uses reflection to read WhereClause, OrderBy, Take, Skip, Select from any args struct.
func (c *TableClient[T]) parseArgs(args interface{}) (whereClause string, orderBy string, take int, skip int, selectCols []string, queryArgs []interface{}) {
	if args == nil {
		return
	}
	v := reflect.ValueOf(args)
	if v.Kind() == reflect.Ptr {
		if v.IsNil() {
			return
		}
		v = v.Elem()
	}
	if v.Kind() != reflect.Struct {
		return
	}

	// Where
	whereField := v.FieldByName("Where")
	if whereField.IsValid() && !whereField.IsNil() {
		// where is a pointer to a model-specific WhereInput struct
		// Delegate to buildWhereFromStruct
		wc, wa := c.buildWhereFromStruct(whereField.Elem(), 1)
		whereClause = wc
		queryArgs = wa
	}

	// OrderBy
	orderByField := v.FieldByName("OrderBy")
	if orderByField.IsValid() && !orderByField.IsNil() {
		obv := orderByField.Elem()
		typ := obv.Type()
		var parts []string
		for i := 0; i < obv.NumField(); i++ {
			fv := obv.Field(i)
			if fv.IsNil() {
				continue
			}
			col := c.quoteName(c.toSnakeCase(typ.Field(i).Name))
			direction := strings.ToUpper(fv.Elem().String())
			if direction != "DESC" {
				direction = "ASC"
			}
			parts = append(parts, col+" "+direction)
		}
		if len(parts) > 0 {
			orderBy = "ORDER BY " + strings.Join(parts, ", ")
		}
	}

	// Take
	takeField := v.FieldByName("Take")
	if takeField.IsValid() && !takeField.IsNil() {
		take = int(takeField.Elem().Int())
	}

	// Skip
	skipField := v.FieldByName("Skip")
	if skipField.IsValid() && !skipField.IsNil() {
		skip = int(skipField.Elem().Int())
	}

	// Select
	selectField := v.FieldByName("Select")
	if selectField.IsValid() && selectField.Kind() == reflect.Slice && !selectField.IsNil() {
		for i := 0; i < selectField.Len(); i++ {
			selectCols = append(selectCols, selectField.Index(i).String())
		}
	}

	return
}

